inline const char* toString(Role value) {
    switch (value) {
        case Role::Chords: return "chords";
        case Role::Pad: return "pad";
        case Role::Arp: return "arp";
        case Role::Bass: return "bass";
        case Role::Melody: return "melody";
        case Role::Counter: return "counter";
        case Role::Drums: return "drums";
    }
    return "?";
}

inline std::optional<Role> parseRole(std::string_view text) {
    if (text == "chords") return Role::Chords;
    if (text == "pad") return Role::Pad;
    if (text == "arp") return Role::Arp;
    if (text == "bass") return Role::Bass;
    if (text == "melody") return Role::Melody;
    if (text == "counter") return Role::Counter;
    if (text == "drums") return Role::Drums;
    return std::nullopt;
}

inline void to_json(json& j, Role value) { j = toString(value); }

inline void from_json(const json& j, Role& value) {
    if (!j.is_string()) throw ParseError("", "expected a string");
    const auto parsed = parseRole(j.get_ref<const std::string&>());
    if (!parsed) throw ParseError("", "unknown role '" + j.get<std::string>() + "'");
    value = *parsed;
}

